<?php echo form_open(get_uri('engenharia/checklists/save'),array('id'=>'engenharia-checklist-form','class'=>'general-form')); ?><div class="modal-body"><input type="hidden" name="id" value="<?php echo (int)$model_info->id; ?>"><div class="form-group"><label>* <?php echo app_lang('name'); ?></label><input class="form-control" name="name" value="<?php echo esc($model_info->name); ?>" data-rule-required="true"></div><div class="form-group"><label>* <?php echo app_lang('code'); ?></label><input class="form-control" name="code" value="<?php echo esc($model_info->code); ?>" data-rule-required="true"></div><div class="form-group"><label>* <?php echo app_lang('engenharia_type'); ?></label><select class="form-select" name="type_id" data-rule-required="true"><?php foreach($types_dropdown as $id=>$label){ ?><option value="<?php echo esc($id); ?>" <?php echo (string)$model_info->type_id===(string)$id?'selected':''; ?>><?php echo esc($label); ?></option><?php } ?></select></div><div class="form-group"><label><?php echo app_lang('description'); ?></label><textarea class="form-control" name="description" rows="4"><?php echo esc($model_info->description); ?></textarea></div></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal"><?php echo app_lang('close'); ?></button><button class="btn btn-primary" type="submit"><?php echo app_lang('save'); ?></button></div><?php echo form_close(); ?><script>$(function(){$('#engenharia-checklist-form').appForm({onSuccess:function(){location.reload();}});});</script>
